edits.newText:
// Register imperative scroll + visibility queries onto the passed handle;
// clear on dispose / handle swap so a stale browser never answers a call.
useEffect(() {
  // `ctrl.tracks` is only valid for the current folder (search session
  // replaces the list), matching the crumb's expectations.
  browserController?._scrollToTrack = scrollToTrack;
  browserController?._isTrackInCurrentFolder = (String path) =>
      ctrl.tracks.any((t) => t.path == path);
  browserController?._isTrackVisible = (String path) {
    if (path.isEmpty) return false;
    // `scrollCacheExtent: 0` + hard clip means a mounted row implies it is
    // within the visible region.
    final rowContext = rowKeys[path]?.currentContext;
    if (rowContext == null) return false;
    final box = rowContext.findRenderObject();
    return box is RenderBox && box.hasSize;
  };

  // Ensure the first frame after layout updates the action visibility.
  WidgetsBinding.instance.addPostFrameCallback((_) {
    if (browserController != null) browserController!.bumpVisibilityEpoch();
  });

  return () {
    browserController?._scrollToTrack = null;
    browserController?._isTrackInCurrentFolder = null;
    browserController?._isTrackVisible = null;
  };
}, [browserController, ctrl]);

